function cookieOptions(maxAge=604800){return `Path=/; Max-Age=${maxAge}; HttpOnly; Secure; SameSite=Lax`}
function normalizeWhatsApp(v=''){const d=String(v).replace(/\D/g,'');if(!d)return '2290197014571';if(d.startsWith('229'))return d;if(d.startsWith('01')&&d.length===10)return '229'+d;if(d.length===8)return '22901'+d;return d}
async function makeToken(env){const data=`${Date.now()}.${crypto.randomUUID()}`;const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(env.ADMIN_PASSWORD),{name:'HMAC',hash:'SHA-256'},false,['sign']);const sig=await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(data));const b64=btoa(String.fromCharCode(...new Uint8Array(sig))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');return `${data}.${b64}`}
async function validToken(req,env){const auth=req.headers.get('Authorization')||'';const ac=auth.match(/^Bearer\s+(.+)$/i);const c=req.headers.get('Cookie')||'',m=c.match(/(?:^|;\s*)bm_admin=([^;]+)/);const token=ac?.[1]||m?.[1];if(!token||!env.ADMIN_PASSWORD)return false;const parts=token.split('.');if(parts.length<3)return false;const data=`${parts[0]}.${parts[1]}`,supplied=parts.slice(2).join('.');try{const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(env.ADMIN_PASSWORD),{name:'HMAC',hash:'SHA-256'},false,['verify']);const bin=atob(supplied.replace(/-/g,'+').replace(/_/g,'/'));return await crypto.subtle.verify('HMAC',key,Uint8Array.from(bin,c=>c.charCodeAt(0)),new TextEncoder().encode(data))}catch{return false}}
async function admin(req,env){return await validToken(req,env)?null:json({error:'Non autorisÃ©'},401)}
async function setting(env,key,f=''){const r=await env.DB.prepare('SELECT value FROM settings WHERE key=?').bind(key).first();return r?.value??f}
function imageArray(v){if(!v)return[];try{const a=JSON.parse(v);if(Array.isArray(a))return a.filter(Boolean)}catch{}return [v]}
function withImages(p){return {...p,images:imageArray(p.image_key)}}

let schemaReady=null;
async function ensureSchema(env){
  if(!env.DB) throw new Error('D1 database binding DB is missing');
  if(schemaReady) return schemaReady;
  schemaReady=(async()=>{
    await env.DB.prepare(`CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,description TEXT DEFAULT '',price INTEGER NOT NULL DEFAULT 0,category TEXT NOT NULL DEFAULT 'Maison',image_key TEXT DEFAULT '',emoji TEXT DEFAULT 'ðï¸',stock INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`).run();
    await env.DB.prepare(`CREATE TABLE IF NOT EXISTS banners (id INTEGER PRIMARY KEY AUTOINCREMENT,image_key TEXT NOT NULL,title TEXT DEFAULT '',subtitle TEXT DEFAULT '',button_text TEXT DEFAULT 'Voir les produits',button_link TEXT DEFAULT '#products',sort_order INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`).run();
    await env.DB.prepare(`CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY,value TEXT NOT NULL DEFAULT '')`).run();
    const addCols=async(table,cols)=>{const rows=(await env.DB.prepare(`PRAGMA table_info(${table})`).all()).results||[];const have=new Set(rows.map(x=>x.name));for(const [name,def] of Object.entries(cols)){if(!have.has(name))await env.DB.prepare(`ALTER TABLE ${table} ADD COLUMN ${name} ${def}`).run()}};
    await addCols('products',{name_en:"TEXT DEFAULT ''",name_zh:"TEXT DEFAULT ''",description_en:"TEXT DEFAULT ''",description_zh:"TEXT DEFAULT ''",category_en:"TEXT DEFAULT ''",category_zh:"TEXT DEFAULT ''"});
    await addCols('banners',{title_en:"TEXT DEFAULT ''",title_zh:"TEXT DEFAULT ''",subtitle_en:"TEXT DEFAULT ''",subtitle_zh:"TEXT DEFAULT ''",button_text_en:"TEXT DEFAULT 'View products'",button_text_zh:"TEXT DEFAULT 'æ¥çåå'"});
    const defaults=[['whatsapp_number','0197014571'],['store_name','BENIN SHOP'],['logo_url',''],['footer_description',''],['footer_contact',''],['footer_address',''],['footer_hours',''],['footer_copyright','Â© 2026 BENIN SHOP']];
    for(const [k,v] of defaults)await env.DB.prepare(`INSERT OR IGNORE INTO settings(key,value) VALUES(?,?)`).bind(k,v).run();
  })().catch(e=>{schemaReady=null;throw e});
  return schemaReady;
}
async function translateOne(text,from,to){if(!text)return '';const url=`https://api.mymemory.translated.net/get?q=${encodeURIComponent(String(text).slice(0,4500))}&langpair=${encodeURIComponent(from+'|'+to)}`;const r=await fetch(url);if(!r.ok)throw new Error('translation service unavailable');const d=await r.json();return d?.responseData?.translatedText||''}
